svg.script:
// 
var mx=10,plotW=1180;function fr(){return document.getElementsByClassName('frame');}function fit(t,name,pw){var m=Math.floor((pw-6)/7);if(m<3){t.style.display='none';return;}t.style.display='';var s=name;if(s.length>m){s=s.substring(0,m-2)+'..';}t.textContent=s;}function place(g,x0,x1,sc){var a=parseFloat(g.getAttribute('data-x0'));var b=parseFloat(g.getAttribute('data-x1'));var r=g.getElementsByTagName('rect')[0];var t=g.getElementsByTagName('text')[0];if(b<=x0||a>=x1){g.style.display='none';return;}g.style.display='';var px=mx+(a-x0)*sc*plotW;var pw=(b-a)*sc*plotW;if(pw<1){pw=1;}r.setAttribute('x',px);r.setAttribute('width',pw);if(t){t.setAttribute('x',px+3);fit(t,g.getAttribute('data-name'),pw);}}function zoom(x0,x1){var sc=1/(x1-x0);var gs=fr();for(var i=0;i<gs.length;i++){place(gs[i],x0,x1,sc);}var d=document.getElementById('details');if(d){d.textContent=(x0>0||x1<1)?'Zoomed - click title or here to reset':'';}}function reset(){zoom(0,1);}window.addEventListener('load',function(){var gs=fr();for(var i=0;i<gs.length;i++){var g=gs[i];var a=parseFloat(g.getAttribute('data-x0'));var b=parseFloat(g.getAttribute('data-x1'));g.onclick=(function(x,y){return function(e){zoom(x,y);if(e){e.stopPropagation();}};})(a,b);}var d=document.getElementById('details');if(d){d.style.cursor='pointer';d.onclick=reset;}var ti=document.getElementById('title');if(ti){ti.style.cursor='pointer';ti.onclick=reset;}});
//
